import java.util.*;
import java.io.*;

public class Test {
    static int readInt() {
        int num = 0;
        boolean neg = false;
        try {
            int ch;
            boolean started = false;
            while ((ch = System.in.read()) != -1) {
                if (ch == '-') {
                    started = true;
                    neg = true;
                    continue;
                }
                if (ch >= '0' && ch <= '9') {
                    started = true;
                    num = num * 10 + ch - '0';
                } else if (started) {
                    break;
                }
            }
        } catch (IOException e) {
        }
        return neg ? -num : num;
    }

    int r, c;
    Scanner scanner = new Scanner(System.in);
    long[][] C = new long[64][64];
    long minDistance = Long.MAX_VALUE;

    void dfs(long x, long y, int v1, int v2) {
        long dist = Math.abs(x - y);
        if (minDistance <= 1 || dist - C[v1][r] * C[v2][r] >= minDistance) return;
        if (v1 == 0 && v2 == 0) {
            if (dist < minDistance) minDistance = dist;
            return;
        }
        if (v1 > 0) {
            long deltaX = C[v1][r] - C[v1 - 1][r], s2 = C[v2][r];
            dfs(x, y + deltaX * s2, v1 - 1, v2);
        }
        if (v2 > 0) {
            long s1 = C[v1][r], deltaY = C[v2][r] - C[v2 - 1][r];
            dfs(x + s1 * deltaY, y, v1, v2 - 1);
        }
    }

    int[] countA = new int[64], countB = new int[64];
    Map<Long, Long> cacheMap = new TreeMap<>();
    char[] seqArr;

    long solve(long x, long y, int v1, int v2) {
        long key = x * 10000 + v1 * 100 + v2;
        Long cachedVal = cacheMap.get(key);
        if (cachedVal != null) return cachedVal;
        long res = 0;
        long d = Math.abs(x - y);
        if (d - C[v1][r] * C[v2][r] > minDistance) {
            cacheMap.put(key, res);
            return res;
        }
        if (v1 == 0 && v2 == 0) return 1;
        char c = seqArr[v1 + v2 - 1];
        if (v1 > 0 && c != 'B') {
            long c1 = C[v1][r] - C[v1 - 1][r], s2 = C[v2][r];
            res += solve(x, y + c1 * s2, v1 - 1, v2);
        }
        if (v2 > 0 && c != 'A') {
            long s1 = C[v1][r], c2 = C[v2][r] - C[v2 - 1][r];
            res += solve(x + s1 * c2, y, v1, v2 - 1);
        }
        cacheMap.put(key, res);
        return res;
    }

    void execute() {
        r = readInt(); c = readInt(); scanner.nextLine();
        seqArr = scanner.nextLine().toCharArray();
        for (int i = 0; i <= 2 * (r + c); i++)
            for (int j = 0; j <= 2 * (r + c); j++) {
                if (j == 0) C[i][j] = 1;
                else if (i == 0) C[i][j] = 0;
                else C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
            }
        int v1 = r + c, v2 = r + c;
        long x = 0, y = 0;
        while (v1 >= r && v2 >= r) {
            if (x > y) {
                long c1 = C[v1][r] - C[v1 - 1][r], s2 = C[v2][r];
                y += c1 * s2;
                v1--;
            } else {
                long s1 = C[v1][r], c2 = C[v2][r] - C[v2 - 1][r];
                x += s1 * c2;
                v2--;
            }
        }
        minDistance = Math.abs(x - y);
        dfs(0, 0, r + c, r + c);
        for (int i = 0; i < 2 * (r + c); i++) {
            countA[i + 1] = countA[i] + (seqArr[i] == 'A' ? 1 : 0);
            countB[i + 1] = countB[i] + (seqArr[i] == 'B' ? 1 : 0);
        }
        long answer = solve(0, 0, r + c, r + c);
        System.out.println(answer);
    }

    public static void main(String[] args) {
        new Test().execute();
    }
}
